function cityEnter(kind){if(!scenes[scene].buildings.some(b=>b[3]===kind))return;if(kind==='orphanage'&&!state.clues.includes('archive')){enter(kind);return}cityInside=kind;cityTreehousePorch=kind==='owlTreehouse';state.cityView={district:scene,room:kind,porch:cityTreehousePorch};persist();cityDraw();cityMessage(cityTreehousePorch?'You arrive beneath the Memorybough. Climb the stairs to enter the story room.':'You step inside '+cityRoomNames[kind]+'. Choose an activity or explore another room.');}
function cityLeave(){cityTreehousePorch=false;cityInside=null;delete state.cityView;persist();cityDraw();cityMessage('You return to '+cityShort[scene]+'.');}
function cityWalk(direction){const i=cityRoute.indexOf(scene);changeScene(cityRoute[(i+direction+cityRoute.length)%cityRoute.length]);cityMessage('You walk into '+cityShort[scene]+'.');}
function cityMessage(text){$('cityResult').textContent=text;}
function cityDraw(){if(!$('cityScene'))return;const info=comfortDetails[scene],isRoom=!!cityInside&&!cityTreehousePorch,key=scene+':'+(cityInside||'street')+':'+cityTreehousePorch;$('area').textContent=isRoom?'INSIDE · '+cityShort[scene].toUpperCase():'A WALK THROUGH '+cityShort[scene].toUpperCase();$('title').textContent=cityTreehousePorch?'Aurelin’s Treehouse':isRoom?cityRoomNames[cityInside]:scenes[scene].name;$('subtitle').textContent=cityTreehousePorch?'Follow the wooden stairs around the Memorybough and step into Aurelin’s story room.':isRoom?comfortPlaceDescription(cityInside):info.intro;$('cityDistrictLabel').textContent=info.icon+' '+cityShort[scene];$('cityHere').textContent=isRoom?cityRoomNames[cityInside]:cityShort[scene]+' · street';$('cityWeather').textContent=(state.minutes>=1080||state.minutes<360?'☾ Evening':'☀ A fresh day')+' · '+(state.weather||'clear');$('hint').textContent=isRoom?'Choose a room, use a work station, or exit to the street.':'Click a building to enter. Walk arrows connect the districts.';$('cityPropertyTag').textContent=isRoom?'YOU ARE INSIDE':'NEIGHBORHOOD EXPLORATION';$('cityScene').dataset.inside=String(isRoom);$('cityScene').style.setProperty('--city-scene-tone',info.tone);
 cityPaintScene();

 if(cityLastScene!==key){cityLastScene=key;cityResetCamera();cityMessage(isRoom?'You have entered '+cityRoomNames[cityInside]+'.':'You arrive in '+cityShort[scene]+'.');}
 if(cityTreehousePorch)$('cityHere').textContent='Memorybough Treehouse · front stairs';cityBuildHotspots();cityBuildActions();cityBuildRoomTrail();cityBuildPeople();cityUpdateMap();cityUpdateStats();comfortObjective();}
function cityTarget(text,x,y,fn,type='door',place){const b=document.createElement('button');b.className='city-scene-target '+type;b.textContent=text;b.style.left=x+'%';b.style.top=y+'%';if(place)b.dataset.place=place;b.addEventListener('pointerdown',e=>e.stopPropagation());b.onclick=e=>{e.stopPropagation();fn()};$('cityHotspots').append(b);return b}
function cityBuildHotspots(){const node=$('cityHotspots');node.innerHTML='';const entries=scenes[scene].buildings;if(cityInside==='owlTreehouse'&&cityTreehousePorch){cityTarget('Enter the story room',58,45,cityEnterStoryRoom,'door');cityTarget('Return to the woodland path',18,62,cityLeave,'exit');return;}if(cityInside){cityTarget(cityWorkLabel(cityInside),49,47,()=>cityUse(cityInside),'work');const i=entries.findIndex(b=>b[3]===cityInside),next=entries[(i+1)%entries.length];if(entries.length>1)cityTarget('Door · '+cityRoomNames[next[3]],82,35,()=>cityEnter(next[3]));cityTarget('Exit to street',13,60,cityLeave,'exit');}else{entries.forEach(([name,x,y,kind],i)=>{const count=entries.length;cityTarget('Enter · '+name,count===1?50:count===2?27+i*46:count>3?18+i*(64/(count-1)):19+i*31,48+(i%2)*7,()=>cityEnter(kind),'door',kind)});cityTarget('Continue along the street →',61,75,()=>cityWalk(1),'path');}}
function cityWorkLabel(kind){return {owlTreehouse:'Listen to Aurelin’s tales',archive:'Inspect the festival register',manor:'Read the search ledger',merchant:'Speak with Elian',oak:'Inspect the silver clasp',orphanage:'Examine the orphanage accounts',carriage:'Inspect the route map',craft:'Work at the bootmaking bench',orders:'Read the courier orders',shop:'Browse furnishings',home:'Make yourself at home',potion:'Brew a healing draught',runes:'Solve the growth runes',tavern:'Sit down for supper',well:'Rest beside the water',lantern:'Light a lantern',game:'Catch lantern lights',court:'Offer counsel',bloodlines:'Explore the family records',garden:'Tend the moonflowers',creatures:'Care for a creature',portraits:'Visit an ancestral home',mysteries:'Open a village case'}[kind]||'Use this room'}
function cityUse(kind){if(kind!==cityInside)return;if(kind==='owlTreehouse'){cityOwlLibrary();return;}enter(kind);if($('modal').open){$('modal').dataset.cityActivity=kind;const photo=document.createElement('img');photo.className='comfort-room-photo';photo.alt=cityRoomNames[kind];photo.src='./assets/interiors/'+comfortRoomImage(kind)+'.jpg';photo.onerror=()=>photo.remove();$('modal').querySelector('h2').parentElement.after(photo);const done=action('Return to '+cityRoomNames[kind],()=>{$('modal').close();cityDraw()});done.className='comfort-secondary';}cityUpdateStats();comfortObjective();cityMessage(state.clues.includes(kind)?'This clue is recorded in your evidence journal.':cityWorkLabel(kind)+'. Take your time with the activity.');}
