function cityBuildActions(){const grid=$('comfortPlaces');grid.innerHTML='';$('comfortPlacesTitle').textContent='What would you like to do?';if(cityInside==='owlTreehouse'&&cityTreehousePorch){cityCard('Climb to the story room','Take the sturdy wooden staircase and enter Aurelin’s furnished home.','Enter the treehouse',cityEnterStoryRoom,'♧');cityCard('Back to the woodland path','Return to the hollow oak and moonwell.','Return to the forest',cityLeave,'↶');return;}if(cityInside){cityCard(cityWorkLabel(cityInside),comfortPlaceDescription(cityInside),'Begin activity',()=>cityUse(cityInside),'✦');cityCard('A moment with a neighbor','Talk to someone connected with this district.','Start a conversation',()=>cityTalk(0),'♡');if(cityInside==='home'){cityCard('A garden of your own','Plant moonflowers and come back when they are ready.','Tend my garden',garden,'❀');cityCard('Dress for the day','Choose a profession and follow its guided assignment.','Choose my role',professions,'✂');}else if(evidence[cityInside])cityCard('Connect the evidence','Review the records you have found in the Silverstitch case.','Open my journal',journal,'▤');else cityCard('The family story','Read the story behind the Silverstitch bloodline.','Read a chapter',()=>comfortReadStory(0),'▤');cityCard('Step back outside','Leave this room and return to the neighborhood street.','Exit to street',cityLeave,'↶');}else{const next=comfortOrder.find(id=>!state.clues.includes(id));for(const [name,x,y,kind]of scenes[scene].buildings){const card=cityCard(name,comfortPlaceDescription(kind),'Enter '+name,()=>cityEnter(kind),comfortDetails[scene].icon,kind);if(kind===next&&state.mode!=='visit')card.classList.add('recommended')}cityCard('Walk the next street','Follow the connected neighborhood route to '+cityShort[cityRoute[(cityRoute.indexOf(scene)+1)%cityRoute.length]]+'.','Continue walking →',()=>cityWalk(1),'➜');}}
function cityBuildRoomTrail(){const trail=$('cityRoomTrail');trail.innerHTML='';if(!cityInside)return;for(const [name,x,y,kind]of scenes[scene].buildings){const b=document.createElement('button');b.textContent=cityRoomNames[kind];b.classList.toggle('selected',kind===cityInside);b.onclick=()=>cityEnter(kind);trail.append(b)}const exit=document.createElement('button');exit.textContent='↶ Street';exit.onclick=cityLeave;trail.append(exit)}
function cityBuildPeople(){const people=$('cityPeople');people.innerHTML='';(cityResidents[scene]||[]).forEach(([name,role],i)=>{const b=document.createElement('button');b.className='city-person';const avatar=document.createElement('span');avatar.className='city-person-avatar';avatar.textContent=name.split(' ').map(w=>w[0]).slice(0,2).join('');const text=document.createElement('span');const strong=document.createElement('strong');strong.textContent=name;const small=document.createElement('small');small.textContent=role;text.append(strong,small);b.append(avatar,text);b.onclick=()=>cityTalk(i);people.append(b)})}
function cityTalk(index){const [name,role,words]=(cityResidents[scene]||[])[index]||cityResidents.capital[0];modal(name+' · '+role,'<p>“'+comfortEscape(words)+'”</p>');action('Back to the neighborhood',()=>$('modal').close())}
function cityUpdateStats(){if(!$('cityStats'))return;const connections=state.visitors.length;const rows=[['Clues recovered',state.clues.length+' / 6'],['Boots crafted',state.crafted],['Home treasures',state.inventory.length],['Friends invited',connections]];$('cityStats').innerHTML=rows.map(([name,n])=>'<div><span>'+name+'</span><strong>'+n+'</strong></div>').join('');const holdings=$('cityHoldings');holdings.innerHTML='';if(!state.inventory.length){holdings.textContent='Your willowwood cottage is yours. Visit the market to choose its first treasure.';}else for(const id of state.inventory){const item=items.find(i=>i[0]===id);if(item){const b=document.createElement('button');b.textContent=item[3]+' '+item[1]+(state.placed.includes(id)?' · placed':' · in your satchel');b.onclick=()=>{changeScene('home');cityEnter('home');cityUse('home')};holdings.append(b)}}$('coins').textContent='✧ '+state.coins+' mooncoins';$('clock').textContent='Day '+(state.day||1)+' · '+hour();}
function cityUpdateMap(){if(!$('cityMap'))return;const map=$('cityMap');map.innerHTML='';const center=document.createElement('div');center.className='city-map-center';center.innerHTML='<span>✦</span><strong>ELDORIA</strong><small>'+comfortEscape(cityShort[scene])+'</small><p>'+(cityTreehousePorch?'At the treehouse stairs':cityInside?'Inside '+comfortEscape(cityRoomNames[cityInside]):'Exploring the neighborhood')+'</p>';map.append(center);const positions=[[4,4],[3,4],[2,4],[1,4],[1,3],[1,2],[1,1],[2,1],[3,1],[4,1],[4,2]];cityRoute.forEach((id,i)=>{const b=document.createElement('button');b.className='city-map-district'+(id===scene?' selected':'');b.style.gridRow=positions[i][0];b.style.gridColumn=positions[i][1];b.style.setProperty('--district-color',comfortDetails[id].tone);b.setAttribute('aria-label','Travel to '+cityShort[id]);b.setAttribute('aria-current',id===scene?'location':'false');const icon=document.createElement('span');icon.textContent=comfortDetails[id].icon;const name=document.createElement('small');name.textContent=cityShort[id];b.append(icon,name);b.onclick=()=>{changeScene(id);if(innerWidth<=950){cityAside.classList.remove('map-shown');$('cityMapButton').textContent='Show map';$('cityScene').scrollIntoView({block:'start'})}};map.append(b)});const owl=document.createElement('button');owl.className='city-map-district'+(cityInside==='owlTreehouse'?' selected':'');owl.style.gridRow=4;owl.style.gridColumn=3;owl.style.setProperty('--district-color','#776b52');owl.setAttribute('aria-label','Travel to Aurelin’s Treehouse');owl.innerHTML='<span>♧</span><small>Aurelin’s Treehouse</small>';owl.onclick=()=>{changeScene('forest');cityEnter('owlTreehouse');if(innerWidth<=950){cityAside.classList.remove('map-shown');$('cityScene').scrollIntoView({block:'start'})}};map.append(owl);}
function cityResetCamera(){cityCamera={x:0,y:0,z:1};cityApplyCamera()}
function cityApplyCamera(){if(!$('citySceneWorld'))return;const limit=(cityCamera.z-1)*42;cityCamera.x=Math.max(-limit,Math.min(limit,cityCamera.x));cityCamera.y=Math.max(-limit*.6,Math.min(limit*.6,cityCamera.y));$('citySceneWorld').style.transform=`translate(${cityCamera.x}%,${cityCamera.y}%) scale(${cityCamera.z})`;$('cityViewLabel').textContent=cityCamera.z>1.05?'CLOSE VIEW · DRAG TO LOOK':'WIDE VIEW · DRAG TO LOOK'}
function cityAdjust(dir){if(dir==='forward')cityCamera.z=Math.min(1.8,cityCamera.z+.15);if(dir==='back')cityCamera.z=Math.max(1,cityCamera.z-.15);if(dir==='left'||dir==='right'){cityCamera.z=Math.max(1.18,cityCamera.z);cityCamera.x+=(dir==='left'?1:-1)*5}cityApplyCamera()}
$('cityScene').addEventListener('pointerdown',e=>{if(e.target.closest('button,a')||e.button!==0)return;cityDrag={x:e.clientX,y:e.clientY,id:e.pointerId};$('cityScene').setPointerCapture(e.pointerId)});
$('cityScene').addEventListener('pointermove',e=>{if(!cityDrag||cityDrag.id!==e.pointerId)return;cityCamera.z=Math.max(1.18,cityCamera.z);cityCamera.x+=(e.clientX-cityDrag.x)/$('cityScene').clientWidth*65;cityCamera.y+=(e.clientY-cityDrag.y)/$('cityScene').clientHeight*35;cityDrag.x=e.clientX;cityDrag.y=e.clientY;cityApplyCamera()});
for(const name of ['pointerup','pointercancel','lostpointercapture'])$('cityScene').addEventListener(name,()=>cityDrag=null);
