window.addEventListener('keydown',e=>{if(e.defaultPrevented||$('modal').open||/INPUT|TEXTAREA|SELECT|BUTTON/.test(e.target.tagName)||e.target.isContentEditable)return;const k=e.key.toLowerCase();const moves={w:'forward',s:'back',a:'left',d:'right'};if(moves[k]){e.preventDefault();cityAdjust(moves[k])}if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();cityWalk(e.key==='ArrowLeft'?-1:1)}if(k==='e'){e.preventDefault();$('cityHotspots button')?.click()}if(k==='m'){e.preventDefault();$('cityMapButton').click()}});
comfortHelp=function(){modal('Your life in Eldoria','<p><strong>Explore like a city:</strong> Walk buttons lead to the next or previous district. The live realm map takes you directly to any neighborhood.</p><p><strong>Step inside:</strong> click a building marker or its activity card. Inside, use the highlighted work station, choose another connected room, or Exit to street.</p><p><strong>Look around:</strong> drag the scene, or use the approach, step-back, and left/right controls. Focus view gives the scene more space. Reset restores the wide view.</p><p><strong>Your adventure:</strong> follow the next-clue panel, gather six records, and connect them in your evidence journal. Crafting, alchemy, furnishing your cottage, and village mysteries remain open.</p><p><strong>Saving:</strong> your existing mooncoins, possessions, and quests are kept. Use Save & backups for a downloaded copy.</p><p>Keyboard: Left/Right changes street, A/D looks around, W/S approaches or steps back, E activates the first scene marker, and M opens the map.</p>');};
