// Each atlas contains four independent photographic environments.
const cityPhotoCatalog={capital:['city-a',0],market:['city-a',1],home:['city-a',2],gardens:['city-a',3],festival:['city-b',0],workshop:['city-b',1],academy:['city-b',2],forest:['city-b',3],forgotten:['city-c',0],court:['city-c',1],library:['city-c',2],treehouse:['city-c',3]};
let cityPhotoRequest=0,cityPhotoLayout=null;
const cityPhotoObserver=new ResizeObserver(()=>cityLayoutPhoto());cityPhotoObserver.observe($('citySceneArt'));
function cityLayoutPhoto(){const a=cityPhotoLayout,el=$('citySceneArt');if(!a||!el)return;const cols=a.atlas?2:1,rows=a.atlas?2:1,ratio=(a.width/cols)/(a.height/rows),w=Math.max(el.clientWidth,el.clientHeight*ratio),h=w/ratio;el.style.backgroundSize=(w*cols)+'px '+(h*rows)+'px';el.style.backgroundPosition=((el.clientWidth-w)/2-(a.cell%cols)*w)+'px '+((el.clientHeight-h)/2-Math.floor(a.cell/cols)*h)+'px';}
function cityPaintScene(){const el=$('citySceneArt'),token=++cityPhotoRequest;let url,cell=0,atlas=false;if(cityTreehousePorch){url='./assets/city/city-c.webp';cell=3;atlas=true;}else if(cityInside){url='./assets/interiors/'+comfortRoomImage(cityInside)+'.jpg';}else{const entry=cityPhotoCatalog[scene];url='./assets/city/'+entry[0]+'.webp';cell=entry[1];atlas=true;}if(window.ELDORIA_SKY?.phase==='night'){if(atlas)url=url.replace('.webp','-night.webp');else if(cityInside==='willowLane')url='./assets/interiors/willow-lane-night.jpg';}if(cityInside&&citySheltered()){const natural=window.ELDORIA_NATURAL_INTERIORS?.photoFor(comfortRoomImage(cityInside));if(natural){url=natural.url;cell=natural.cell;atlas=true;}}el.innerHTML='<div class="city-photo-loading">Opening the neighborhood…</div>';el.style.backgroundImage='none';cityPhotoLayout=null;let status=document.querySelector('.city-art-status');if(!status){status=document.createElement('span');status.className='city-art-status';$('cityScene').append(status)}status.textContent='PHOTOGRAPHIC SCENE';const image=new Image();image.onload=()=>{if(token!==cityPhotoRequest)return;el.innerHTML='';el.style.backgroundImage='url("'+url+'")';cityPhotoLayout={atlas,cell,width:image.naturalWidth,height:image.naturalHeight,url};cityLayoutPhoto();$('cityScene').dataset.photoReady='true';};image.onerror=()=>{if(token!==cityPhotoRequest)return;el.innerHTML='<div class="city-photo-loading">This scene could not load. Try another district or refresh.</div>';status.textContent='SCENE UNAVAILABLE · ACTIVITIES STILL WORK';$('cityScene').dataset.photoReady='false';};$('cityScene').dataset.photoReady='loading';image.src=url;}
const cityImageBefore=comfortRoomImage;comfortRoomImage=function(kind){return ({willowLane:'willow-lane',pipHome:'neighbor-pip',fernHome:'neighbor-fern',cobbleHome:'neighbor-cobble',willowHome:'neighbor-willow',countyCamp:'county-camp',midnightMarket:'county-market',moonGarden:'county-garden',legacyRoom:'county-legacy',countyBakery:'tavern',originalShop:'original-shoemaker',memoryHall:'library',spellAtelier:'runes'})[kind]||(kind==='owlTreehouse'?'treehouse':cityImageBefore(kind))};
const cityDescriptionBefore=comfortPlaceDescription;comfortPlaceDescription=function(kind){return kind==='owlTreehouse'?'Visit the old Memorybough, climb to Aurelin’s treehouse, and settle into a real story room with sixteen tales.':cityDescriptionBefore(kind)};
function cityEnterStoryRoom(){if(cityInside!=='owlTreehouse')return;cityTreehousePorch=false;state.cityView={district:'forest',room:'owlTreehouse',porch:false};persist();cityDraw();cityMessage('You step from the wooden porch into Aurelin’s warm story room.');}
function cityOwlLibrary(){modal('Aurelin · Keeper of the Memorybough','<p>Lantern light warms the wooden shelves. Aurelin settles on his perch beside the great window. “Draw close, Templar. Which tale shall we share?”</p>');(window.ELDORIA_OWL_TALES||[]).forEach((t,i)=>action(t.title,()=>cityOwlBook(i,0)));action('Return to the story room',()=>$('modal').close())}
let cityNarration=null;function cityStopNarration(){if(cityNarration){window.speechSynthesis?.cancel();cityNarration=null;}}
function cityOwlBook(index,page){cityStopNarration();const tale=window.ELDORIA_OWL_TALES?.[index];if(!tale)return;state.owlStories??=[];if(!state.owlStories.includes(index))state.owlStories.push(index);persist();modal('Aurelin · '+tale.title,'<div class="comfort-story"><p>'+comfortEscape(tale.pages[page])+'</p></div><p class="comfort-chapter-label">PAGE '+(page+1)+' OF '+tale.pages.length+'</p>');if(page>0)action('← Previous page',()=>cityOwlBook(index,page-1));if(page<tale.pages.length-1)action('Continue the tale →',()=>cityOwlBook(index,page+1));else action('Choose another tale',cityOwlLibrary);if(window.speechSynthesis&&window.SpeechSynthesisUtterance){action('Listen to Aurelin',()=>{cityStopNarration();cityNarration=new SpeechSynthesisUtterance(tale.pages[page]);cityNarration.lang='en-US';cityNarration.rate=.88;cityNarration.pitch=.85;const voices=speechSynthesis.getVoices().filter(v=>/^en/.test(v.lang));if(voices.length)cityNarration.voice=voices[0];speechSynthesis.speak(cityNarration)});action('Stop reading aloud',cityStopNarration)}action('Return to the story room',()=>{cityStopNarration();$('modal').close()})}
$('modal').addEventListener('close',cityStopNarration);
const cityModalBefore=modal;modal=function(...args){cityStopNarration();cityModalBefore(...args);for(const panel of $('modal').querySelectorAll('div[style*="linear-gradient"]'))panel.remove()};
// The cottage photograph replaces the old emoji illustration; owned furnishings remain usable.
const cityHomeBefore=home;home=function(){cityHomeBefore();$('modal').querySelector('div[style*="linear-gradient"]')?.remove();};
cityDraw();
// The street view stays alive while you are playing; menus and hidden tabs pause the clock.
let cityClockMark=performance.now(),cityClockSeconds=0;
setInterval(()=>{const now=performance.now(),dt=Math.min(2,(now-cityClockMark)/1000);cityClockMark=now;if(window.ELDORIA_ATMOSPHERE?.realClock)return;if(document.visibilityState!=='visible'||$('modal').open||$('cityEntrance')&&!$('cityEntrance').hidden)return;cityClockSeconds+=dt;if(cityClockSeconds>=8){cityClockSeconds-=8;advanceRealmTime(1);$('clock').textContent='Day '+(state.day||1)+' · '+hour();}},1000);
function cityEntrance(){let entered=false;try{entered=sessionStorage.getItem('eldoria-city-entered')==='yes'}catch{}if(entered)return;const entry=document.createElement('section');entry.id='cityEntrance';entry.setAttribute('aria-labelledby','cityEntranceTitle');entry.innerHTML=`<div class="city-entrance-art"></div><div class="city-entrance-content"><span class="city-eyebrow">THE FAIRY-TALE BLOODLINES</span><div class="city-entrance-mark">Eldoria</div><h1 id="cityEntranceTitle">A kingdom to call your own.</h1><p>Your cottage. Your neighbors. Your next chapter.</p><div class="city-entrance-choices"><button id="cityEntranceContinue">Enter Eldoria</button><button id="cityEntranceHome">Begin at my cottage</button></div><p class="city-entrance-resume">Your journey continues in ${comfortEscape(cityShort[scene])}. Your saved life is kept.</p></div>`;document.body.append(entry);document.body.classList.add('city-entrance-open');const art=entry.querySelector('.city-entrance-art');function layoutEntry(){const ratio=1.5,w=Math.max(art.clientWidth,art.clientHeight*ratio),h=w/ratio;art.style.backgroundSize=(w*2)+'px '+(h*2)+'px';art.style.backgroundPosition=((art.clientWidth-w)/2)+'px '+((art.clientHeight-h)/2)+'px';}const entryObserver=new ResizeObserver(layoutEntry);entryObserver.observe(art);layoutEntry();function dismiss(){entryObserver.disconnect();entry.hidden=true;document.body.classList.remove('city-entrance-open');try{sessionStorage.setItem('eldoria-city-entered','yes')}catch{}$('cityScene').focus({preventScroll:true})}$('cityEntranceContinue').onclick=dismiss;$('cityEntranceHome').onclick=()=>{changeScene('home');cityEnter('home');dismiss()};$('cityEntranceContinue').focus();}
cityEntrance();
